  ('20000000-0000-4000-8000-000000000002', 'demo-user-2', '파도 소리가 오래 남은 오후', '대왕암공원 산책길 끝에서 잠시 멈춰 바다를 바라보았던 가상의 기억.', '대왕암공원', '2021-10-16', 'meaningful', 'public', 0, 'exact', 35.4926, 129.4391, 35.4926, 129.4391, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000005', 'demo-user-3', '가족과 처음 찾은 정원', '가족과 처음 국가정원을 둘러보며 사진을 여러 장 남겼던 가상의 기억.', '태화강 국가정원', '2020-10-04', 'happy', 'public', 0, 'exact', 35.5502, 129.2903, 35.5502, 129.2903, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000006', 'demo-user-1', '혼자 달린 자전거 길', '복잡한 생각을 정리하려고 강변을 천천히 달렸던 가상의 기억.', '태화강 국가정원 산책로', '2022-08-27', 'lonely', 'public', 1, 'exact', 35.5503, 129.2897, 35.5503, 129.2897, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000007', 'demo-user-2', '처음 마주한 봄 꽃밭', '햇빛 아래 펼쳐진 꽃밭의 색이 유난히 선명했던 가상의 순간.', '태화강 국가정원', '2023-04-09', 'excited', 'public', 0, 'exact', 35.5498, 129.2905, 35.5498, 129.2905, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000008', 'demo-user-3', '오래된 친구와 다시 만난 곳', '오랫동안 연락하지 못했던 친구와 다시 만나 밀린 이야기를 나눈 가상의 기억.', '태화강 국가정원 산책로', '2025-09-13', 'love', 'public', 1, 'exact', 35.5497, 129.2896, 35.5497, 129.2896, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000009', 'demo-user-1', '비가 그친 뒤의 잔디 냄새', '울산대공원을 천천히 걷다가 비가 그친 뒤의 공기를 기억해 둔 가상의 이야기.', '울산대공원', '2018-07-14', 'nostalgic', 'public', 0, 'exact', 35.5317, 129.2935, 35.5317, 129.2935, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000010', 'demo-user-2', '골목의 작은 불빛', '성남동 골목을 지나며 가게 불빛이 하나씩 켜지는 모습을 바라본 가상의 기억.', '성남동 문화의거리', NULL, 'meaningful', 'public', 1, 'approximate', 35.5558, 129.3193, 35.56, 129.32, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000011', 'demo-user-3', '수업이 끝난 늦은 오후', '울산대학교 주변을 걸으며 다음 학기를 천천히 상상해 본 가상의 기억.', '울산대학교 주변', '2024-03-22', 'meaningful', 'public', 0, 'exact', 35.5438, 129.2592, 35.5438, 129.2592, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
