  ('20000000-0000-4000-8000-000000000015', 'demo-user-2', '햇살이 따뜻했던 공원 벤치', '새 학기를 앞두고 울산대공원 벤치에 앉아 작은 계획을 적어 보았던 가상의 기억.', '울산대공원', '2026-03-07', 'happy', 'public', 1, 'exact', 35.5322, 129.2941, 35.5322, 129.2941, '2026-09-10T00:00:00.000Z', '2026-09-10T00:00:00.000Z'),
